using System;
using System.Collections.Concurrent;
using System.Collections.Generic;

namespace Eggnog.Relations.Benchmarks
{

    /// <summary>
    /// A union-find workload of egglog's <c>union-find/benches/union-find.rs</c>: seed operations applied while the
    /// input is prepared, and the operations the benchmark measures. Generated by the same algorithms as egglog's
    /// <c>prepare_operations_random</c> and <c>prepare_operations_local</c>, from a seeded <see cref="Random"/>.
    /// </summary>
    /// <remarks>
    /// egglog draws from <c>rand::rng()</c>, seeded from the OS, and prepares a new workload for every sample; this
    /// generates one workload per parameter set from a fixed seed, so every variant (serial, every thread count, work
    /// stealing) runs the same operations. Identifiers are <see cref="uint"/> where egglog's are <c>usize</c>; every
    /// identifier is at most the item count.
    /// </remarks>
    internal sealed class UnionFindWorkload
    {

        /// <summary>
        /// The number of operations of each workload already generated, by kind, item count and seed.
        /// </summary>
        static readonly ConcurrentDictionary<(UnionFindWorkloadKind, int, int), int> operationCounts = new();

        /// <summary>
        /// Initializes a new instance.
        /// </summary>
        /// <param name="seedOperations">The operations applied before the measurement.</param>
        /// <param name="operations">The measured operations.</param>
        UnionFindWorkload(UnionFindOperation[] seedOperations, UnionFindOperation[] operations)
        {
            SeedOperations = seedOperations;
            Operations = operations;
        }

        /// <summary>
        /// Gets the operations applied while the input is prepared (egglog's <c>seed_operations</c>).
        /// </summary>
        public UnionFindOperation[] SeedOperations { get; }

        /// <summary>
        /// Gets the operations the benchmark measures (egglog's <c>operations</c>).
        /// </summary>
        public UnionFindOperation[] Operations { get; }

        /// <summary>
        /// Generates the workload of <paramref name="kind"/> over <paramref name="itemCount"/> identifiers.
        /// </summary>
        /// <param name="kind">The workload shape.</param>
        /// <param name="itemCount">The number of identifiers (egglog's <c>n_items</c>).</param>
        /// <param name="randomSeed">The random seed.</param>
        /// <returns>The workload.</returns>
        public static UnionFindWorkload Prepare(UnionFindWorkloadKind kind, int itemCount, int randomSeed) => kind switch
        {
            UnionFindWorkloadKind.Random => PrepareRandom(itemCount, randomSeed),
            UnionFindWorkloadKind.Local => PrepareLocal(itemCount, randomSeed),
            _ => throw new ArgumentOutOfRangeException(nameof(kind), kind, "Unknown workload kind."),
        };

        /// <summary>
        /// Gets the number of measured operations of the workload <see cref="Prepare"/> generates for these arguments,
        /// generating it the first time. For the throughput column, which runs where no workload was generated.
        /// </summary>
        /// <param name="kind">The workload shape.</param>
        /// <param name="itemCount">The number of identifiers.</param>
        /// <param name="randomSeed">The random seed.</param>
        /// <returns>The length of <see cref="Operations"/>.</returns>
        public static int OperationCount(UnionFindWorkloadKind kind, int itemCount, int randomSeed)
        {
            return operationCounts.GetOrAdd(
                (kind, itemCount, randomSeed),
                static key => Prepare(key.Item1, key.Item2, key.Item3).Operations.Length);
        }

        /// <summary>
        /// egglog's <c>prepare_operations_random</c>: for each identifier <c>i</c> of the first quarter, a union with a
        /// uniformly random identifier, seeded with probability 0.9 and measured otherwise; then <c>2 n</c> finds of
        /// random identifiers; the measured operations shuffled.
        /// </summary>
        /// <param name="itemCount">The number of identifiers.</param>
        /// <param name="randomSeed">The random seed.</param>
        /// <returns>The workload.</returns>
        public static UnionFindWorkload PrepareRandom(int itemCount, int randomSeed)
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(itemCount, 1);

            var random = new Random(randomSeed);
            var seedOperations = new List<UnionFindOperation>();
            var operations = new List<UnionFindOperation>(2 * itemCount + itemCount / 4);
            for (var i = 0; i < itemCount / 4; i++)
            {
                if (NextBool(random, 0.9))
                    seedOperations.Add(UnionFindOperation.Union((uint)i, (uint)random.Next(itemCount)));
                else
                    operations.Add(UnionFindOperation.Union((uint)i, (uint)random.Next(itemCount)));
            }

            for (var i = 0; i < 2 * itemCount; i++)
                operations.Add(UnionFindOperation.Find((uint)random.Next(itemCount)));

            var shuffled = operations.ToArray();
            random.Shuffle(shuffled);
            return new UnionFindWorkload(seedOperations.ToArray(), shuffled);
        }

        /// <summary>
        /// egglog's <c>prepare_operations_local</c>: each identifier <c>i</c>, with probability 0.15, gets a union with
        /// <c>min(i + r, n)</c> for <c>r</c> uniform in [0, 1000), seeded with probability 0.9 and measured otherwise;
        /// then <c>2 n</c> finds of random identifiers; the measured operations stably sorted by first identifier
        /// (Rust's <c>sort_by_key</c> is stable).
        /// </summary>
        /// <param name="itemCount">The number of identifiers.</param>
        /// <param name="randomSeed">The random seed.</param>
        /// <returns>The workload.</returns>
        public static UnionFindWorkload PrepareLocal(int itemCount, int randomSeed)
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(itemCount, 1);

            var random = new Random(randomSeed);
            var seedOperations = new List<UnionFindOperation>();
            var operations = new List<UnionFindOperation>(2 * itemCount + itemCount / 64);
            for (var i = 0; i < itemCount; i++)
            {
                // Only create unions for 15% of the items.
                if (NextBool(random, 0.85))
                    continue;

                var right = (uint)Math.Min(i + random.Next(1000), itemCount);
                if (NextBool(random, 0.9))
                    seedOperations.Add(UnionFindOperation.Union((uint)i, right));
                else
                    operations.Add(UnionFindOperation.Union((uint)i, right));
            }

            for (var i = 0; i < 2 * itemCount; i++)
                operations.Add(UnionFindOperation.Find((uint)random.Next(itemCount)));

            return new UnionFindWorkload(seedOperations.ToArray(), SortByLeft(operations, itemCount));
        }

        /// <summary>
        /// Applies <paramref name="operations"/> to a serial union-find, in order: the loop egglog's benches run.
        /// </summary>
        /// <param name="unionFind">The union-find.</param>
        /// <param name="operations">The operations.</param>
        public static void Apply(UnionFind unionFind, ReadOnlySpan<UnionFindOperation> operations)
        {
            foreach (ref readonly var operation in operations)
            {
                if (operation.IsUnion)
                    unionFind.Union(operation.Left, operation.Right);
                else
                    unionFind.Find(operation.Left);
            }
        }

        /// <summary>
        /// Applies <paramref name="operations"/> to a concurrent union-find, in order: the loop each egglog worker runs.
        /// </summary>
        /// <param name="unionFind">The union-find.</param>
        /// <param name="operations">The operations.</param>
        public static void Apply(ConcurrentUnionFind unionFind, ReadOnlySpan<UnionFindOperation> operations)
        {
            foreach (ref readonly var operation in operations)
            {
                if (operation.IsUnion)
                    unionFind.Union(operation.Left, operation.Right);
                else
                    unionFind.Find(operation.Left);
            }
        }

        /// <summary>
        /// Computes the root of every identifier in [0, <paramref name="maxId"/>] after <paramref name="seedOperations"/>
        /// and <paramref name="operations"/>, with a serial union-find. Both union-finds link by minimum identifier, so
        /// the root of a class is its minimum member whatever the order of the unions: a concurrent run must end with
        /// exactly these roots. O(operations + maxId).
        /// </summary>
        /// <param name="maxId">The largest identifier to report.</param>
        /// <param name="seedOperations">The seed operations.</param>
        /// <param name="operations">The measured operations.</param>
        /// <returns>The root of each identifier.</returns>
        public static uint[] ReferenceRoots(
            int maxId,
            ReadOnlySpan<UnionFindOperation> seedOperations,
            ReadOnlySpan<UnionFindOperation> operations)
        {
            var unionFind = new UnionFind();
            unionFind.Find((uint)maxId);
            Apply(unionFind, seedOperations);
            Apply(unionFind, operations);

            var roots = new uint[maxId + 1];
            for (var i = 0; i < roots.Length; i++)
                roots[i] = unionFind.FindNaive((uint)i);

            return roots;
        }

        /// <summary>
        /// Checks that every identifier of <paramref name="expected"/> has the expected root in
        /// <paramref name="unionFind"/>. Must not race other operations. O(identifiers).
        /// </summary>
        /// <param name="unionFind">The union-find.</param>
        /// <param name="expected">The expected roots, from <see cref="ReferenceRoots"/>.</param>
        /// <exception cref="InvalidOperationException">An identifier has another root.</exception>
        public static void VerifyRoots(ConcurrentUnionFind unionFind, uint[] expected)
        {
            for (var i = 0; i < expected.Length; i++)
            {
                var root = unionFind.Find((uint)i);
                if (root != expected[i])
                    throw new InvalidOperationException(
                        $"The concurrent union-find gives identifier {i} the root {root}; the serial reference gives {expected[i]}.");
            }
        }

        /// <summary>
        /// Checks that every identifier of <paramref name="expected"/> has the expected root in
        /// <paramref name="unionFind"/>, with <see cref="UnionFind.FindNaive"/>. O(identifiers).
        /// </summary>
        /// <param name="unionFind">The union-find.</param>
        /// <param name="expected">The expected roots, from <see cref="ReferenceRoots"/>.</param>
        /// <exception cref="InvalidOperationException">An identifier has another root.</exception>
        public static void VerifyRoots(UnionFind unionFind, uint[] expected)
        {
            for (var i = 0; i < expected.Length; i++)
            {
                var root = unionFind.FindNaive((uint)i);
                if (root != expected[i])
                    throw new InvalidOperationException(
                        $"The union-find gives identifier {i} the root {root}; the serial reference gives {expected[i]}.");
            }
        }

        /// <summary>
        /// Draws <c>true</c> with probability <paramref name="probability"/>: rand's <c>random_bool</c>.
        /// </summary>
        /// <param name="random">The random source.</param>
        /// <param name="probability">The probability, in [0, 1].</param>
        /// <returns>The draw.</returns>
        static bool NextBool(Random random, double probability) => random.NextDouble() < probability;

        /// <summary>
        /// Sorts <paramref name="operations"/> stably by <see cref="UnionFindOperation.Left"/>, which lies in
        /// [0, <paramref name="maxKey"/>], with a counting sort. O(operations + maxKey).
        /// </summary>
        /// <param name="operations">The operations.</param>
        /// <param name="maxKey">The largest key.</param>
        /// <returns>The sorted operations.</returns>
        static UnionFindOperation[] SortByLeft(List<UnionFindOperation> operations, int maxKey)
        {
            var starts = new int[maxKey + 2];
            foreach (var operation in operations)
                starts[operation.Left + 1]++;

            for (var k = 1; k < starts.Length; k++)
                starts[k] += starts[k - 1];

            var sorted = new UnionFindOperation[operations.Count];
            foreach (var operation in operations)
                sorted[starts[operation.Left]++] = operation;

            return sorted;
        }

    }

}
